function openAttachment(file,download=false){const url=URL.createObjectURL(new Blob([file.bytes],{type:file.media_type})),link=document.createElement('a');link.href=url;if(download)link.download=file.display_name;else{link.target='_blank';link.rel='noopener';}document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
