function renderReport(){let mapped;try{mapped=mapper();}catch(error){return fatal(error);}reportCreatedAt=reportCreatedAt??new Date().toISOString();const report=buildRecoveryMapReport(draft,{activationConfig,attachments,review:mapped.review,version,createdAt:reportCreatedAt,rehearsalCompleted}),section=(id,title,content)=>`<section class="card report-section" id="report-${id}"><h2>${title}</h2>${content}<button class="secondary" data-edit="${id}">修改此部分</button></section>`;app.innerHTML=`<h1>Recovery Map Report</h1><section class="card"><h2>报告总览</h2><dl class="report-overview"><div><dt>名称</dt><dd>${escape(report.title)}</dd></div><div><dt>Version</dt><dd>${report.version}</dd></div><div><dt>创建/更新</dt><dd>${escape(report.created_at)} / ${escape(report.updated_at)}</dd></div><div><dt>平台账户</dt><dd>${report.account_count}</dd></div><div><dt>附件</dt><dd>${report.attachment_count}</dd></div><div><dt>完成状态</dt><dd>${report.completion_status}</dd></div><div><dt>恢复演练</dt><dd>${report.rehearsal_status}</dd></div></dl></section><nav class="card report-directory"><h2>目录</h2>${[['assets-accounts','资产与账户清单'],['recovery-conditions','恢复所需条件与资料'],['locations-finding','位置与查找'],['recovery-order-exceptions','恢复与转移步骤'],['contacts-assistance','协助人'],['evidence-messages','给未来恢复人的嘱托'],['attachments','附件目录']].map(([id,label])=>`<a href="#report-${id}">${label}</a>`).join('')}</nav>${section('assets-accounts','资产与账户清单',report.accounts.map(account=>`<article><h3>${escape(account.label)}</h3><p>${escape(account.region||'地区未填写')} · ${escape(optionLabel(account.account_class)||'账户类型未填写')}</p></article>`).join('')||'<p>暂无账户</p>')}${section('recovery-conditions','恢复所需条件与资料',report.accounts.map(account=>`<article><h3>${escape(account.label)}</h3><p>${account.conditions.map(item=>`<span class="chip">${escape(item.label)}</span>`).join(' ')||'未选择条件'}</p></article>`).join(''))}${section('locations-finding','位置与查找',report.accounts.map(account=>`<article><h3>${escape(account.label)}</h3>${account.conditions.map(item=>`<p><strong>${escape(item.label)}：</strong>${item.location?.covered_by_summary?'汇总材料覆盖':escape([item.location?.type,item.location?.label,item.location?.finding_instructions].filter(Boolean).join(' · ')||'未完成')}</p>`).join('')}</article>`).join(''))}${section('recovery-order-exceptions','恢复与转移步骤',report.accounts.map(account=>`<article><h3>${escape(account.label)}</h3><p>${escape(account.step?.action||'使用步骤附件或尚未完成')}</p>${account.risk_notes?`<p><strong>风险提示：</strong>${escape(account.risk_notes)}</p>`:''}</article>`).join(''))}${section('contacts-assistance','协助人',report.assistance.map(item=>`<p>${escape([item.label,item.role,item.when_to_contact,item.can_help,item.assistance_boundary].filter(Boolean).join(' · '))}</p>`).join('')||'<p>未设置协助人</p>')}${section('evidence-messages','给未来恢复人的嘱托',`<p>${escape(report.message||'未留言')}</p>`)}${section('attachments','附件目录',report.attachments.map(file=>`<article class="file-row"><div><strong>${escape(file.display_name)}</strong><small>${escape(file.media_type)} · ${formatBytes(file.byte_length)} · ${escape(file.purpose)}</small></div><button class="secondary" data-view="${file.id}">查看</button><button class="secondary" data-download="${file.id}">下载</button></article>`).join('')||'<p>暂无附件</p>')}<div class="actions"><button id="report-back" class="secondary">返回Dashboard</button><button id="report-review">进入最终Review</button></div>`;document.querySelector('#report-back').onclick=dashboard;document.querySelector('#report-review').onclick=renderReview;document.querySelectorAll('[data-edit]').forEach(node=>node.onclick=()=>renderModule(node.dataset.edit));document.querySelectorAll('[data-view]').forEach(node=>node.onclick=()=>openAttachment(attachments.find(item=>item.id===node.dataset.view)));document.querySelectorAll('[data-download]').forEach(node=>node.onclick=()=>openAttachment(attachments.find(item=>item.id===node.dataset.download),true));}

function issueText(issue){const messages={ASSET_REQUIRED:'请至少添加一项资产或账户。',ACCOUNT_PLATFORM_REQUIRED:'请选择平台。',ACCOUNT_REGION_REQUIRED:'请选择账户所属国家或地区。',ACCOUNT_CLASS_REQUIRED:'请选择个人或机构账户。',ACCOUNT_NICKNAME_REQUIRED:'同平台多账户需要不同的备注名称。',CONDITION_SELECTION_REQUIRED:'该账户尚未选择恢复条件。',CONDITION_NOT_READY:'恢复条件仍是临时状态。',CONDITION_LOCATION_REQUIRED:'已选择条件缺少位置条目。',LOCATION_TYPE_REQUIRED:'请选择位置类型。',LOCATION_NAME_REQUIRED:'请填写位置名称。',LOCATION_CONTENT_REQUIRED:'尚未说明位置，也没有覆盖该条件的附件。',STEP_CONTENT_REQUIRED:'请填写恢复与转移步骤或上传步骤附件。',PLATFORM_SAVE_REQUIRED:'该平台内容有未保存修改。',ATTACHMENT_INVALID:'附件为空、读取不完整、校验失败或归属不明确。',PERSONAL_ACCOUNT_ONLY:'当前阶段不支持机构账户。',CONSERVATIVE_REGION_FALLBACK:'当前地区知识范围有限，执行前请确认官方流程。'};return messages[issue.message_key||issue.code]||`请完成${issue.condition_label||issue.field_id||'此项内容'}。`;}
function renderReviewLegacy(){let result;try{result=mapper();reviewRevision=draftRevision;}catch(error){return fatal(error);}const rows=(items,type)=>items.map(item=>`<article class="issue"><div><strong>${escape(item.asset_label||item.platform_label||'Recovery Map')}</strong>${item.condition_label?`<span class="chip">${escape(item.condition_label)}</span>`:''}<p>${escape(issueText(item))}</p>${item.temporary_state?`<p><strong>当前状态：</strong>${escape(optionLabel(item.temporary_state))}</p>`:''}${item.why_needed?`<p><strong>为什么：</strong>${escape(item.why_needed)}</p>`:''}${item.how_to_fix?`<p><strong>如何补充：</strong>${escape(item.how_to_fix)}</p>`:''}<small>${item.blocking?'阻止生成':'可跳过'}${item.escalation&&item.escalation!=='NONE'?` · 需要${item.escalation==='HUMAN_LEGAL'?'人工/法律':'官方'}升级`:''}</small></div><button class="secondary" data-fix="${item.navigation_target?.module_id||item.module_id||''}" data-entity="${item.navigation_target?.entity_id||item.entity_id||''}" data-field="${item.navigation_target?.field_id||item.field_id||''}">返回准确修改</button></article>`).join('')||`<p class="success">${type==='blocking'?'没有阻止生成的问题。':'关键说明已经具备。'}</p>`;app.innerHTML=`<h1>恢复地图检查</h1><p>此页面只展示Mapper与统一规则的结果，不在UI维护第二套判断。</p><section class="card"><h2>必须修复</h2>${rows(result.review.blocking,'blocking')}</section><section class="card"><h2>建议补充</h2>${rows(result.review.attention,'attention')}</section><div id="message"></div><div class="actions"><button id="review-back" class="secondary">返回Recovery Map</button><button id="password" ${result.review.valid?'':'disabled'}>设置恢复密码</button></div>`;document.querySelector('#review-back').onclick=dashboard;document.querySelector('#password').onclick=renderPassword;document.querySelectorAll('[data-fix]').forEach(button=>button.onclick=()=>button.dataset.fix?renderModule(button.dataset.fix,{focusEntity:button.dataset.entity,focusField:button.dataset.field}):dashboard());}
function renderReview(){let result;try{result=mapper();reviewRevision=draftRevision;}catch(error){return fatal(error);}const labels=moduleLabels(),rows=items=>items.map(item=>`<article class="issue"><div><strong>${escape(item.platform_label)} · ${escape(item.asset_label)}</strong><dl><div><dt>模块</dt><dd>${escape(labels[item.module_id]||item.module_id)}</dd></div><div><dt>条件或字段</dt><dd>${escape(item.condition_label||item.field_id)}</dd></div><div><dt>当前值/状态</dt><dd>${escape(item.temporary_state?optionLabel(item.temporary_state):item.current_value||'未完成')}</dd></div></dl><p><strong>问题：</strong>${escape(issueText(item))}</p><p><strong>为什么必须：</strong>${escape(item.why_needed)}</p><p><strong>如何完成：</strong>${escape(item.how_to_fix)}</p><small>${item.blocking?'阻断最终生成':'不阻断'}${item.skippable?' · 可跳过':''}</small></div><button class="secondary" data-fix="${item.navigation_target.module_id}" data-entity="${item.navigation_target.entity_id||''}" data-field="${item.navigation_target.field_id||''}">返回准确修改</button></article>`).join('')||'<p class="success">没有阻止生成的问题。</p>';app.innerHTML=`<h1>最终Review</h1><p>所有判断来自Rulebook 1.1.0和统一Rule Engine。</p><section class="card"><h2>必须修复</h2>${rows(result.review.blocking)}</section><section class="card"><h2>知识范围与建议</h2>${rows(result.review.attention)}</section><div class="actions"><button id="review-back" class="secondary">返回Report</button><button id="password" ${result.review.valid&&reportCreatedAt?'':'disabled'}>设置恢复密码</button></div>`;document.querySelector('#review-back').onclick=renderReport;document.querySelector('#password').onclick=renderPassword;document.querySelectorAll('[data-fix]').forEach(button=>button.onclick=()=>renderModule(button.dataset.fix,{focusEntity:button.dataset.entity,focusField:button.dataset.field}));}
