function renderPassword(){app.innerHTML=`<h1>设置恢复密码</h1><section class="card"><label>恢复密码<input id="password-value" type="password" autocomplete="new-password"></label><label>再次输入<input id="confirmation" type="password" autocomplete="new-password"></label><div id="password-status"></div><label class="choice"><input id="ack" type="checkbox">我理解平台不能找回恢复密码</label><div id="message"></div></section><div class="actions"><button id="password-back" class="secondary">返回检查</button><button id="generate" disabled>生成恢复材料</button></div>`;document.querySelector('#password-back').onclick=renderReview;document.querySelector('#generate').onclick=generate;document.querySelectorAll('input').forEach(node=>{node.onkeydown=event=>{if(event.key==='Enter')event.preventDefault();};node.addEventListener(node.type==='checkbox'?'change':'input',updatePassword);});updatePassword();}
